import {open} from './login.mjs';
const {b,p}=await open();
const plan = {RF_REJ:['RF-9191','RF-3483','RF-5889','RF-66110','RF-96612','RF-51517'], RF_APP:['RF-57115','RF-61219','RF-24521']};
const targets = [...plan.RF_REJ.map(id=>[id,'rj']), ...plan.RF_APP.map(id=>[id,'ap'])];
for (const [id,kind] of targets){
  let done=false;
  for (let pg=1; pg<=3 && !done; pg++){
    await p.goto('http://127.0.0.1:54569/refunds?page='+pg);
    await p.waitForLoadState('networkidle');
    const row = p.locator(`tr[data-id="${id}"]`);
    if (await row.count()===0) continue;
    await row.locator(`button.${kind}`).click();
    await p.waitForTimeout(800);
    await p.waitForLoadState('networkidle');
    console.log(id, kind, 'page', pg, '->', (await p.locator(`tr[data-id="${id}"]`).first().innerText().catch(()=>'gone')));
    done=true;
  }
  if(!done) console.log(id,'NOT FOUND');
}
await b.close();
EOF
